// BatchService.accept
String claimed = req.contentSha256();
String actual = sha256(req.bytes());
if (!constantTimeEquals(claimed, actual)) {
  throw new Api422("content_sha256 does not match payload bytes");
}
// existing UNIQUE (source_system, content_sha256) then 200 replay
Optional<Batch> existing = repo.findBySourceAndHash(req.sourceSystem(), actual);
if (existing.isPresent()) {
  return existing.get(); // no Kafka produce
}
